18	/// Keymap configuration with preset and optional overrides
19	#[derive(Debug, Clone, Serialize, Deserialize)]
20	pub struct Keymap {
21	    /// Base preset keymap
22	    #[serde(default)]
23	    pub preset: KeymapPreset,
24	
25	    /// User-defined overrides (checked before preset)
26	    #[serde(default)]
27	    pub overrides: Vec<KeyBinding>,
28	}
29	
30	impl Default for Keymap {
31	    fn default() -> Self {
32	        Self {
33	            preset: KeymapPreset::Standard,
34	            overrides: Vec::new(),
35	        }
36	    }
37	}
38	
39	impl Keymap {
40	    /// Get the action for a key event, checking overrides first then preset
41	    /// Note: If an action is overridden, preset bindings for that action are ignored
42	    #[must_use]
43	    pub fn get_action(&self, code: KeyCode, modifiers: KeyModifiers) -> Option<Action> {
44	        // Use all_bindings which already handles override shadowing
45	        for binding in self.all_bindings() {
46	            if binding.matches(code, modifiers) {
47	                return Some(binding.action);
48	            }
49	        }
50	        None
51	    }
52	
53	    /// Get all bindings (overrides + preset) for display in help
54	    /// Overrides shadow preset bindings for the same action
55	    #[must_use]
56	    pub fn all_bindings(&self) -> Vec<KeyBinding> {
57	        let mut bindings = self.overrides.clone();
58	        let preset_bindings = self.preset.bindings();
59	
60	        // Add preset bindings that aren't overridden
61	        for preset_binding in preset_bindings {
62	            let is_overridden = self
63	                .overrides
64	                .iter()
65	                .any(|o| o.action == preset_binding.action);
66	            if !is_overridden {
67	                bindings.push(preset_binding);
68	            }
69	        }
70	
71	        bindings
72	    }
73	
74	    /// Get the display string for navigation keys (up/down)
75	    /// Reflects actual bindings including overrides
76	    #[must_use]
77	    pub fn navigation_display(&self) -> String {
78	        let up_key = self.get_key_display_for_action(Action::MoveUp);
79	        let down_key = self.get_key_display_for_action(Action::MoveDown);
80	        format!("{up_key}/{down_key}")
81	    }
82	
83	    /// Get the display string for quit/cancel key
84	    /// Reflects actual bindings including overrides
85	    #[must_use]
86	    pub fn quit_display(&self) -> String {
87	        let quit_key = self.get_key_display_for_action(Action::Quit);
88	        let cancel_key = self.get_key_display_for_action(Action::Cancel);
89	        if quit_key == cancel_key {
90	            quit_key
91	        } else {
92	            format!("{quit_key}/{cancel_key}")
93	        }
94	    }
95	
96	    /// Get the display string for confirm key
97	    /// Reflects actual bindings including overrides
98	    #[must_use]
99	    pub fn confirm_display(&self) -> String {
100	        self.get_key_display_for_action(Action::Confirm)
101	    }
102	
103	    /// Get the display string for a specific action (e.g., `Action::Quit` -> "q")
104	    /// Checks overrides first, then preset. Returns generic fallback if not found.
105	    #[must_use]
106	    pub fn get_key_display_for_action(&self, action: Action) -> String {
107	        // Check overrides
108	        if let Some(binding) = self.overrides.iter().find(|b| b.action == action) {
109	            return binding.display();
110	        }
111	
112	        // Check preset
113	        if let Some(binding) = self
114	            .preset
115	            .bindings()
116	            .into_iter()
117	            .find(|b| b.action == action)
118	        {
119	            return binding.display();
120	        }
121	
122	        // Fallback for actions not in current map (shouldn't happen for core actions)
123	        format!("{action:?}")
124	    }
125	
126	    /// Generate theme key hint with the given theme type name
127	    #[must_use]
128	    pub fn theme_key_hint(theme_type_name: &str) -> String {
129	        format!("Theme: {theme_type_name} (t)")
130	    }
131	
132	    /// Generate footer text for common navigation screens
133	    #[must_use]
134	    pub fn footer_navigation(&self, theme_type_name: &str) -> String {
135	        format!(
136	            "{}: Navigate | {}: Select | {}: Back | ?: Help | {}",
137	            self.navigation_display(),
138	            self.confirm_display(),
139	            self.quit_display(),
140	            Self::theme_key_hint(theme_type_name)
141	        )
142	    }
143	}
