44	        if let Ok(parsed) = self.parse() {
45	            // Normalize character keys with Shift: uppercase char with SHIFT -> lowercase char with SHIFT
46	            let (normalized_code, normalized_modifiers) = normalize_shift_char(code, modifiers);
