73	/// Normalize Shift+character for consistent matching.
74	///
75	/// This handles terminal behavior variations:
76	/// - Some terminals send Char('G') + SHIFT for Shift+G
77	/// - Some terminals send Char('G') + NONE for Shift+G (just uppercase, no modifier)
78	///
79	/// We normalize both to Char('g') + SHIFT for consistent matching.
80	fn normalize_shift_char(code: KeyCode, modifiers: KeyModifiers) -> (KeyCode, KeyModifiers) {
81	    if let KeyCode::Char(c) = code {
82	        if c.is_ascii_uppercase() {
83	            // Uppercase letter - treat as shift+lowercase regardless of whether SHIFT modifier is present
84	            // This handles terminals that don't send SHIFT modifier with uppercase letters
85	            let mut new_modifiers = modifiers;
86	            new_modifiers.insert(KeyModifiers::SHIFT);
87	            return (KeyCode::Char(c.to_ascii_lowercase()), new_modifiers);
88	        }
89	    }
90	    (code, modifiers)
91	}
